require_once $_SERVER['DOCUMENT_ROOT'] . '/analytics/tracker.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/creator-ai/auth/config.php';
$pdo = db();
$smartToozAds = [];
try {
    $stmt = $pdo->query("SELECT ad_key, enabled, ad_code FROM ads_settings");
    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $smartToozAds[(string)$row['ad_key']] = ['enabled' => (int)($row['enabled'] ?? 0), 'ad_code' => (string)($row['ad_code'] ?? '')];
    }
} catch (Throwable $e) { $smartToozAds = []; }
function smartToozAd(string $adKey): void { global $smartToozAds; if (!isset($smartToozAds[$adKey]) || (int)$smartToozAds[$adKey]['enabled'] !== 1) return; $code = trim((string)$smartToozAds[$adKey]['ad_code']); if ($code !== '') echo $code; }
smartToozAd('popunder');
smartToozAd('socialbar');
