<script>
const textInput=document.getElementById('textInput'),counter=document.getElementById('counter'),copyBtn=document.getElementById('copyBtn'),clearBtn=document.getElementById('clearBtn');
function toUpperCaseText(){textInput.value=textInput.value.toUpperCase();updateCounter();focusText()}function toLowerCaseText(){textInput.value=textInput.value.toLowerCase();updateCounter();focusText()}function toTitleCase(){textInput.value=textInput.value.toLowerCase().replace(/(^|\s)([a-z])/g,(m,s,l)=>s+l.toUpperCase());updateCounter();focusText()}function toSentenceCase(){const text=textInput.value.toLowerCase();let result='',capitalizeNext=true;for(let i=0;i<text.length;i++){const char=text[i];if(capitalizeNext&&/[a-z]/i.test(char)){result+=char.toUpperCase();capitalizeNext=false}else result+=char;if(char==='.'||char==='!'||char==='?')capitalizeNext=true}textInput.value=result;updateCounter();focusText()}function toAlternatingCase(){const text=textInput.value;let result='',letterIndex=0;for(let i=0;i<text.length;i++){const char=text[i];if(/[a-z]/i.test(char)){result+=letterIndex%2===0?char.toLowerCase():char.toUpperCase();letterIndex++}else result+=char}textInput.value=result;updateCounter();focusText()}function toInverseCase(){const text=textInput.value;let result='';for(let i=0;i<text.length;i++){const char=text[i];if(char===char.toUpperCase()&&char!==char.toLowerCase())result+=char.toLowerCase();else if(char===char.toLowerCase()&&char!==char.toUpperCase())result+=char.toUpperCase();else result+=char}textInput.value=result;updateCounter();focusText()}function updateCounter(){const length=textInput.value.length;counter.textContent=length+(length===1?' character':' characters')}function focusText(){textInput.focus()}
copyBtn.addEventListener('click',async function(){const text=textInput.value;if(text.trim()===''){copyBtn.textContent='Nothing to Copy';setTimeout(()=>copyBtn.textContent='📋 Copy Text',1500);return}try{await navigator.clipboard.writeText(text);copyBtn.textContent='✓ Copied!'}catch(error){const temp=document.createElement('textarea');temp.value=text;document.body.appendChild(temp);temp.select();try{document.execCommand('copy');copyBtn.textContent='✓ Copied!'}catch(e){copyBtn.textContent='Copy Failed'}document.body.removeChild(temp)}setTimeout(()=>copyBtn.textContent='📋 Copy Text',1500)});clearBtn.addEventListener('click',()=>{textInput.value='';updateCounter();textInput.focus()});textInput.addEventListener('input',updateCounter);function toggleMenu(){document.getElementById('navLinks').classList.toggle('open')}updateCounter();
</script>
